function validate([nums1, nums2]) {
  if (!Array.isArray(nums1) || !Array.isArray(nums2)) return 'nums1 and nums2 must be arrays.';
  const n = nums1.length;
  if (n < 2 || n > 100000) return 'nums1 needs 2 to 100000 values.';
  if (nums2.length !== n) return 'nums1 and nums2 must have the same length.';
  if ([...nums1, ...nums2].some(v => !Number.isInteger(v) || v < 0 || v > n)) return 'Each value is an integer from 0 to the array length.';
  return null;
}

