function beautifulPair(nums1, nums2) {
  const n = nums1.length;
  const firstSeen = new Map();
  let duplicate = null;
  for (let i = 0; i < n; i++) {
    const key = nums1[i] * (n + 1) + nums2[i];
    if (!firstSeen.has(key)) {
      firstSeen.set(key, i);
    } else if (duplicate === null || firstSeen.get(key) < duplicate[0]) {
      duplicate = [firstSeen.get(key), i];
    }
  }
  if (duplicate !== null) {
    return duplicate;
  }

  const order = Array.from({ length: n }, (_, i) => i);
  order.sort((a, b) => nums1[a] - nums1[b]);
  let best = [Infinity, -1, -1];

  const consider = (a, b) => {
    const dist = Math.abs(nums1[a] - nums1[b]) + Math.abs(nums2[a] - nums2[b]);
    const i = Math.min(a, b);
    const j = Math.max(a, b);
    if (dist < best[0] || (dist === best[0] && (i < best[1] || (i === best[1] && j < best[2])))) {
      best = [dist, i, j];
    }
  };

  const solve = (left, right) => {
    if (right - left <= 3) {
      for (let a = left; a < right; a++) {
        for (let b = a + 1; b < right; b++) {
          consider(order[a], order[b]);
        }
      }
      return;
    }
    const mid = (left + right) >> 1;
    const midX = nums1[order[mid]];
    solve(left, mid);
    solve(mid, right);
    const strip = [];
    for (let k = left; k < right; k++) {
      if (Math.abs(nums1[order[k]] - midX) <= best[0]) {
        strip.push(order[k]);
      }
    }
    strip.sort((a, b) => nums2[a] - nums2[b]);
    for (let a = 0; a < strip.length; a++) {
      for (let b = a + 1; b < strip.length && nums2[strip[b]] - nums2[strip[a]] <= best[0]; b++) {
        consider(strip[a], strip[b]);
      }
    }
  };

  solve(0, n);
  return [best[1], best[2]];
}

