function beautifulPair(nums1, nums2) {
  let answer = null;
  let least = Infinity;
  for (let i = 0; i < nums1.length; i++) {
    for (let j = i + 1; j < nums1.length; j++) {
      const d = Math.abs(nums1[i] - nums1[j]) + Math.abs(nums2[i] - nums2[j]);
      // Pairs arrive in lexicographic order, so only a strictly smaller distance replaces the answer.
      if (d < least) { least = d; answer = [i, j]; }
    }
  }
  return answer;
}

