function generate(rand, size) {
  const int = (lo, hi) => lo + Math.floor(rand() * (hi - lo + 1));
  if (size === 'small') {
    const n = int(2, 9);
    const top = rand() < 0.5 ? Math.min(n, 3) : n;
    return [Array.from({ length: n }, () => int(0, top)), Array.from({ length: n }, () => int(0, top))];
  }
  const n = int(1500, 2000);
  const mode = rand();
  if (mode < 0.2) {
    return [Array.from({ length: n }, () => int(0, n)), Array.from({ length: n }, () => int(0, n))];
  }
  // Distinct points: either spread out, or packed on a coarse lattice so many pairs tie.
  const lattice = mode < 0.6;
  const side = lattice ? 50 : n;
  const used = new Set();
  const nums1 = [];
  const nums2 = [];
  while (nums1.length < n) {
    const x = lattice ? 2 * int(0, side - 1) : int(0, n);
    const y = lattice ? 2 * int(0, side - 1) : int(0, n);
    if (used.has(x * 4096 + y)) continue;
    used.add(x * 4096 + y);
    nums1.push(x);
    nums2.push(y);
  }
  return [nums1, nums2];
}
